//! IPC contract for the UI (FUNCTIONAL_SPEC §2, §4; docs/STACK.md "IPC layer").
//!
//! Commands are schema-driven: every command and DTO carries `specta::Type` and
//! TypeScript bindings are generated by tauri-specta at debug build time
//! (../ui/src/bindings.ts) - hand-written bindings are not allowed.
//!
//! Commands run as async fns: sync Tauri commands execute on the main thread,
//! so long loading (§2 non-blocking requirement) must not be sync.

use serde::Serialize;

use logviewer_core::format::Format;
use logviewer_core::highlights::{HighlightEngine, Rule};
use logviewer_core::matching::Matcher;
use logviewer_core::parser::Level;
use logviewer_core::visibility::Visibility;
use logviewer_core::workspace::FileModel;

/// Shared app state: the currently loaded file, if any.
pub type FileState = std::sync::Mutex<Option<FileModel>>;

pub fn new_file_state() -> FileState {
  std::sync::Mutex::new(None)
}

/// Shared visibility state (§7, §10.1, §11): the core engine plus the shell
/// bookkeeping the engine does not store (pattern texts, mirrors of the on/off
/// switches it cannot expose, disabled categories across reloads, the cached
/// visible-line list).
pub type VisState = std::sync::Mutex<VisibilityState>;

pub fn new_visibility_state() -> VisState {
  std::sync::Mutex::new(VisibilityState::new())
}

fn lock_err() -> String {
  "state poisoned".to_owned()
}

// ---------------------------------------------------------------- DTOs

// spec interpretation: levels travel as lowercase long names ("critical",
// "error", "warning", "msg", "debug", "trace"); short codes are a UI detail.
pub fn level_name(level: Level) -> &'static str {
  match level {
    Level::Critical => "critical",
    Level::Error => "error",
    Level::Warning => "warning",
    Level::Msg => "msg",
    Level::Debug => "debug",
    Level::Trace => "trace",
  }
}

pub fn format_name(format: Format) -> &'static str {
  match format {
    Format::Ksiva => "ksiva",
    Format::Plain => "plain",
  }
}

#[derive(Debug, Clone, Serialize, specta::Type)]
pub struct CategoryCount {
  pub path: String,
  pub count: u32,
}

#[derive(Debug, Clone, Serialize, specta::Type)]
pub struct LevelCount {
  pub level: String,
  pub count: u32,
}

#[derive(Debug, Clone, Serialize, specta::Type)]
pub struct LoadResult {
  /// Detected format: "ksiva" or "plain" (§3).
  pub format: String,
  pub line_count: u32,
  pub categories: Vec<CategoryCount>,
  pub levels: Vec<LevelCount>,
  /// Load time in milliseconds (diagnostics; §16 monitoring).
  pub load_ms: u32,
}

#[derive(Debug, Clone, Serialize, specta::Type)]
pub struct RowDto {
  /// 1-based line number in the source file.
  pub line_no: u32,
  pub time_display: String,
  pub category: String,
  pub level: String,
  pub message: String,
  // spec interpretation: the raw line travels as lossy UTF-8 text; raw bytes
  // with invalid encoding cannot be represented in the webview strings anyway.
  pub raw: String,
  /// §9 highlight spans of the Message text (empty: no active rule). Byte
  /// offsets inside `message` — kept raw, converted in ipcClient.ts.
  pub spans: Vec<SpanDto>,
}

pub fn level_order() -> [Level; 6] {
  [
    Level::Critical,
    Level::Error,
    Level::Warning,
    Level::Msg,
    Level::Debug,
    Level::Trace,
  ]
}

pub fn to_load_result(model: &FileModel, load_ms: u32) -> LoadResult {
  LoadResult {
    format: format_name(model.format()).to_owned(),
    line_count: model.line_count() as u32,
    categories: model
      .categories()
      .map(|(path, count)| CategoryCount {
        path: path.to_owned(),
        count: count as u32,
      })
      .collect(),
    // §11 counters: fixed level order, zero counts included.
    levels: level_order()
      .into_iter()
      .map(|level| LevelCount {
        level: level_name(level).to_owned(),
        count: model.level_count(level) as u32,
      })
      .collect(),
    load_ms,
  }
}

pub fn to_row_dto(row: &logviewer_core::parser::Row) -> RowDto {
  RowDto {
    line_no: row.line_no,
    time_display: row.time_display.clone(),
    category: row.category.clone(),
    level: level_name(row.level).to_owned(),
    message: row.message.clone(),
    raw: String::from_utf8_lossy(&row.raw).into_owned(),
    // Highlights are shell state, so the shared mapper starts spanless; the
    // get_rows reader fills the spans in for active rules.
    spans: Vec::new(),
  }
}

// ------------------------------------------------------- visibility bridge
// Contract: docs/notes/visibility-bridge.md (RAW shapes; normalization to UI
// shapes lives only in ui/src/ipcClient.ts).

/// One text criterion of the snapshot (filter or pin). `id` = index in the
/// filters/pins list of the LATEST snapshot.
#[derive(Debug, Clone, PartialEq, Serialize, specta::Type)]
pub struct CriterionDto {
  pub id: u32,
  pub mode: String,
  pub pattern: String,
  pub enabled: bool,
}

/// One level button of the snapshot: `enabled` is the toggle state, `count`
/// is the §11 counter (level toggles IGNORED).
#[derive(Debug, Clone, Serialize, specta::Type)]
pub struct LevelStateDto {
  pub level: String,
  pub enabled: bool,
  pub count: u32,
}

/// The single read command's shape (contract, raw snake_case).
#[derive(Debug, Clone, Serialize, specta::Type)]
pub struct VisibilitySnapshotDto {
  pub visible_count: u32,
  pub levels: Vec<LevelStateDto>,
  pub filters: Vec<CriterionDto>,
  pub pins: Vec<CriterionDto>,
  pub categories_enabled: Vec<String>,
  /// §9 highlight rules (they survive reloads; opposite of pins).
  pub highlights: Vec<HighlightDto>,
}

/// Shell metadata for one core `Criterion`: the engine stores only the
/// compiled matcher, the side panels need the original mode tag, pattern text
/// and a mirror of the enabled switch the engine does not expose.
struct CriterionMeta {
  mode: String,
  pattern: String,
  enabled: bool,
}

/// Shell-managed visibility state over the loaded file (§7, §10.1, §11).
pub struct VisibilityState {
  vis: Visibility,
  /// Parallel to the engine's filter list (same order, same length).
  filter_meta: Vec<CriterionMeta>,
  /// Parallel to the engine's pin list.
  pin_meta: Vec<CriterionMeta>,
  /// Mirror of the engine's level switches, in `level_order()` order — the
  /// engine has no getter, and the snapshot reports these values.
  levels_enabled: [bool; 6],
  /// Category paths the user disabled; they survive reloads by name while
  /// new categories start enabled (contract policy 3, §2.1/§10).
  disabled_categories: std::collections::BTreeSet<String>,
  /// Cached visible 1-based line numbers; `None` = invalidated by a mutation
  /// or a file load, recomputed on the next read command.
  visible_cache: Option<Vec<u32>>,
}

impl Default for VisibilityState {
  fn default() -> Self {
    Self::new()
  }
}

impl VisibilityState {
  fn new() -> VisibilityState {
    VisibilityState {
      vis: Visibility::new(),
      filter_meta: Vec::new(),
      pin_meta: Vec::new(),
      levels_enabled: [true; 6],
      disabled_categories: std::collections::BTreeSet::new(),
      visible_cache: None,
    }
  }

  /// Adds one criterion (filter or pin) from the wire parts, keeping the
  /// shell metadata list parallel to the engine's own list.
  fn add_criterion(&mut self, mode: &str, pattern: &str, is_filter: bool) -> Result<(), String> {
    let matcher = matcher_from_parts(mode, pattern)?;
    let meta = CriterionMeta {
      mode: mode.to_owned(),
      pattern: pattern.to_owned(),
      enabled: true,
    };
    if is_filter {
      self.filter_meta.push(meta);
      self.vis.add_filter(matcher);
    } else {
      self.pin_meta.push(meta);
      self.vis.add_pin(matcher);
    }
    Ok(())
  }

  /// Recomputes the visible-line cache from `model` when invalidated. With
  /// no file loaded the visible set is empty.
  fn ensure_visible_cache(&mut self, model: Option<&FileModel>) {
    if self.visible_cache.is_none() {
      self.visible_cache = Some(model.map_or_else(Vec::new, |m| self.vis.visible_lines(m)));
    }
  }

  fn invalidate(&mut self) {
    self.visible_cache = None;
  }
}

/// Mode strings of the contract — the same tags `filtersTab.ts` FilterMode
/// uses. An invalid pattern (bad regex, syntax error, non-numeric lineno)
/// compiles to a matcher that matches nothing (`Matcher::never()`); an
/// unknown mode tag is refused (contract: mode is one of the four).
fn matcher_from_parts(mode: &str, pattern: &str) -> Result<Matcher, String> {
  match mode {
    "plain" => Ok(Matcher::plain(pattern)),
    "regex" => Ok(Matcher::regex(pattern)),
    "simple" => Ok(Matcher::simple(pattern)),
    "lineno" => Ok(pattern
      .trim()
      .parse::<u32>()
      .map_or_else(|_| Matcher::never(), Matcher::line_no)),
    other => Err(format!("unknown mode {other:?}: expected plain|regex|simple|lineno")),
  }
}

fn criterion_err(which: &str, id: u32) -> String {
  format!("no such {which} {id}")
}

fn level_from_name(name: &str) -> Option<Level> {
  level_order().into_iter().find(|&l| level_name(l) == name)
}

pub(crate) fn add_filter_inner(vis: &VisState, mode: &str, pattern: &str) -> Result<(), String> {
  let mut guard = vis.lock().map_err(|_| lock_err())?;
  guard.invalidate();
  guard.add_criterion(mode, pattern, true)
}

pub(crate) fn add_pin_inner(vis: &VisState, mode: &str, pattern: &str) -> Result<(), String> {
  let mut guard = vis.lock().map_err(|_| lock_err())?;
  guard.invalidate();
  guard.add_criterion(mode, pattern, false)
}

pub(crate) fn set_filter_enabled_inner(vis: &VisState, id: u32, on: bool) -> Result<(), String> {
  let mut guard = vis.lock().map_err(|_| lock_err())?;
  let id = id as usize;
  let meta = guard
    .filter_meta
    .get_mut(id)
    .ok_or_else(|| criterion_err("filter", id as u32))?;
  meta.enabled = on;
  guard.vis.set_filter_enabled(id, on);
  guard.invalidate();
  Ok(())
}

pub(crate) fn set_pin_enabled_inner(vis: &VisState, id: u32, on: bool) -> Result<(), String> {
  let mut guard = vis.lock().map_err(|_| lock_err())?;
  let id = id as usize;
  let meta = guard
    .pin_meta
    .get_mut(id)
    .ok_or_else(|| criterion_err("pin", id as u32))?;
  meta.enabled = on;
  guard.vis.set_pin_enabled(id, on);
  guard.invalidate();
  Ok(())
}

pub(crate) fn remove_filter_inner(vis: &VisState, id: u32) -> Result<(), String> {
  let mut guard = vis.lock().map_err(|_| lock_err())?;
  let id = id as usize;
  if id >= guard.filter_meta.len() {
    return Err(criterion_err("filter", id as u32));
  }
  guard.filter_meta.remove(id);
  guard.vis.remove_filter(id); // bounds-checked above, never panics
  guard.invalidate();
  Ok(())
}

pub(crate) fn remove_pin_inner(vis: &VisState, id: u32) -> Result<(), String> {
  let mut guard = vis.lock().map_err(|_| lock_err())?;
  let id = id as usize;
  if id >= guard.pin_meta.len() {
    return Err(criterion_err("pin", id as u32));
  }
  guard.pin_meta.remove(id);
  guard.vis.remove_pin(id); // bounds-checked above, never panics
  guard.invalidate();
  Ok(())
}

/// Drop every pin (§12: the rmp command and the §2.1 reload reset). The
/// engine stores only compiled matchers, so the shell removes them by
/// popping the front until both parallel lists are empty.
pub(crate) fn clear_pins_inner(vis: &VisState) -> Result<(), String> {
  let mut guard = vis.lock().map_err(|_| lock_err())?;
  while !guard.pin_meta.is_empty() {
    // Both lists are parallel: remove the same front index from each.
    guard.vis.remove_pin(0);
    guard.pin_meta.remove(0);
  }
  guard.invalidate();
  Ok(())
}

/// Drop every filter (§13: the rmf command); the engine stores only
/// compiled matchers, so the same front-popping clearing applies.
pub(crate) fn clear_filters_inner(vis: &VisState) -> Result<(), String> {
  let mut guard = vis.lock().map_err(|_| lock_err())?;
  while !guard.filter_meta.is_empty() {
    // Both lists are parallel: remove the same front index from each.
    guard.vis.remove_filter(0);
    guard.filter_meta.remove(0);
  }
  guard.invalidate();
  Ok(())
}

pub(crate) fn set_level_enabled_inner(vis: &VisState, level: &str, on: bool) -> Result<(), String> {
  let level = level_from_name(level)
    .ok_or_else(|| format!("no such level {level:?}: expected critical|error|warning|msg|debug|trace"))?;
  let mut guard = vis.lock().map_err(|_| lock_err())?;
  let idx = level_order()
    .iter()
    .position(|&l| l == level)
    .expect("level_order covers all six levels");
  guard.levels_enabled[idx] = on;
  guard.vis.set_level_enabled(level, on);
  guard.invalidate();
  Ok(())
}

pub(crate) fn set_category_enabled_inner(vis: &VisState, path: &str, on: bool) -> Result<(), String> {
  let mut guard = vis.lock().map_err(|_| lock_err())?;
  guard.vis.set_category_enabled(path, on);
  if on {
    guard.disabled_categories.remove(path);
  } else {
    guard.disabled_categories.insert(path.to_owned());
  }
  guard.invalidate();
  Ok(())
}

/// Contract policy 3: after a load the whitelist is repopulated as
/// `model.categories() - disabled_categories` (disabled survive by name,
/// new categories start enabled); levels, filters and pins persist because
/// the core Visibility object simply lives across reloads.
///
/// spec interpretation: every ancestor prefix of a category is enabled
/// alongside it — the engine requires the exact path AND all ancestors in
/// the whitelist (§10: disabling a node hides its children), and the core
/// doc comment fixes the load population as "FileModel::categories and the
/// category tree nodes". Without the ancestors a two-level category whose
/// parent has no rows of its own would load invisible. A disabled path
/// stays out of the whitelist; a disabled PARENT therefore also keeps its
/// children hidden after a reload, which is the §10 behavior.
fn repopulate_categories(vis: &mut VisibilityState, model: &FileModel) {
  for (path, _) in model.categories() {
    let mut prefix = path;
    loop {
      if !vis.disabled_categories.contains(prefix) {
        vis.vis.set_category_enabled(prefix, true);
      }
      match prefix.rfind('/') {
        Some(i) => prefix = &prefix[..i],
        None => break,
      }
    }
  }
}

/// Snapshot for the read command; locks in file-then-visibility-then-
/// highlights order everywhere the mutexes are taken together
/// (no interleaving; highlights are independent of both others).
pub(crate) fn visibility_snapshot_inner(
  file: &FileState,
  vis: &VisState,
  hl: &HighlightState,
) -> Result<VisibilitySnapshotDto, String> {
  let file = file.lock().map_err(|_| lock_err())?;
  let mut vis = vis.lock().map_err(|_| lock_err())?;
  vis.ensure_visible_cache(file.as_ref());
  let hl = hl.lock().map_err(|_| lock_err())?;
  let counts: [u64; 6] = file
    .as_ref()
    .map_or([0_u64; 6], |m| vis.vis.level_counts_excluding_levels(m));
  let highlights = highlight_dtos(&hl);
  Ok(VisibilitySnapshotDto {
    visible_count: vis
      .visible_cache
      .as_ref()
      .map_or(0, |lines| lines.len()) as u32,
    levels: level_order()
      .into_iter()
      .enumerate()
      .map(|(i, level)| LevelStateDto {
        level: level_name(level).to_owned(),
        enabled: vis.levels_enabled[i],
        count: counts[i] as u32,
      })
      .collect(),
    filters: vis
      .filter_meta
      .iter()
      .enumerate()
      .map(|(id, m)| CriterionDto {
        id: id as u32,
        mode: m.mode.clone(),
        pattern: m.pattern.clone(),
        enabled: m.enabled,
      })
      .collect(),
    pins: vis
      .pin_meta
      .iter()
      .enumerate()
      .map(|(id, m)| CriterionDto {
        id: id as u32,
        mode: m.mode.clone(),
        pattern: m.pattern.clone(),
        enabled: m.enabled,
      })
      .collect(),
    categories_enabled: vis.vis.categories_enabled().iter().cloned().collect(),
    highlights,
  })
}

/// A window of the VISIBLE sequence (contract; §4: `offset` indexes rows
/// passing §7, not raw line numbers).
pub(crate) fn get_rows_inner(
  offset: u32,
  limit: u32,
  file: &FileState,
  vis: &VisState,
  hl: &HighlightState,
) -> Result<Vec<RowDto>, String> {
  let file = file.lock().map_err(|_| lock_err())?;
  let Some(model) = file.as_ref() else {
    // No file loaded: empty (current behavior, contract).
    return Ok(Vec::new());
  };
  let mut vis = vis.lock().map_err(|_| lock_err())?;
  vis.ensure_visible_cache(Some(model));
  let hl = hl.lock().map_err(|_| lock_err())?;
  let lines = vis.visible_cache.as_deref().unwrap_or(&[]);
  let start = (offset as usize).min(lines.len());
  let end = start.saturating_add(limit as usize).min(lines.len());
  let window = lines.get(start..end).unwrap_or(&[]);
  // A cheap guard first: with no active rule every row gets an empty spans
  // list (to_row_dto default) and nothing else is computed.
  let has_active = hl.engine.rules().iter().any(|h| h.enabled);
  Ok(window
    .iter()
    .map(|&line| {
      let row = model
        .row(line as usize - 1)
        .expect("cached visible lines exist in the model");
      let mut dto = to_row_dto(row);
      if has_active {
        dto.spans = row_span_dtos(&hl, row);
      }
      dto
    })
    .collect::<Vec<_>>())
}

// ------------------------------------------------------------- search (§8)

/// Search result for the §8 panel: `positions` are 0-based indexes of the
/// VISIBLE sequence, ascending; `total` is their count («k of N» uses N).
#[derive(Debug, Clone, PartialEq, Serialize, specta::Type)]
pub struct SearchMatchDto {
  pub total: u32,
  pub positions: Vec<u32>,
}

/// Search over the shell's cached visible sequence (§8): the core matcher
/// (case-insensitivity and never-match on invalid patterns live there) runs
/// against the same lossy raw text the §7 engine filters on. Search modes
/// are plain|regex|simple only (lineno is a filter mode); an unknown mode is
/// refused in the dsq.3 style, an empty pattern is «0 of 0», and an unloaded
/// file has nothing to search.
pub(crate) fn search_visible_inner(
  file: &FileState,
  vis: &VisState,
  mode: &str,
  pattern: &str,
) -> Result<SearchMatchDto, String> {
  let matcher = match mode {
    "plain" => Matcher::plain(pattern),
    "regex" => Matcher::regex(pattern),
    "simple" => Matcher::simple(pattern),
    other => {
      return Err(format!("unknown mode {other:?}: expected plain|regex|simple"));
    }
  };
  // Contract: an empty pattern means «0 of 0», not a match-everything search.
  if pattern.is_empty() {
    return Ok(SearchMatchDto {
      total: 0,
      positions: Vec::new(),
    });
  }
  // File-then-visibility lock order, as in visibility_snapshot_inner.
  let file = file.lock().map_err(|_| lock_err())?;
  let Some(model) = file.as_ref() else {
    // No file loaded: nothing to search, whatever the visibility state holds.
    return Ok(SearchMatchDto {
      total: 0,
      positions: Vec::new(),
    });
  };
  let mut vis = vis.lock().map_err(|_| lock_err())?;
  vis.ensure_visible_cache(Some(model));
  let lines = vis.visible_cache.as_deref().unwrap_or(&[]);
  let mut positions = Vec::new();
  for (idx, &line) in lines.iter().enumerate() {
    let row = model
      .row(line as usize - 1)
      .expect("cached visible lines exist in the model");
    let text = String::from_utf8_lossy(&row.raw);
    if matcher.matches(&text, row.line_no) {
      positions.push(idx as u32);
    }
  }
  Ok(SearchMatchDto {
    total: positions.len() as u32,
    positions,
  })
}

// ------------------------------------------------------- highlights (§9)

/// Shared highlight state (§9): the core engine plus the shell bookkeeping
/// the engine does not store (mode tags, pattern texts, user override colors,
/// mirrors of the on/off switches). Highlights SURVIVE a file reload (§2.1 —
/// the opposite policy of pins), and they never touch the visible cache:
/// coloring does not change which rows are visible.
pub type HighlightState = std::sync::Mutex<HighlightShellState>;

pub fn new_highlight_state() -> HighlightState {
  std::sync::Mutex::new(HighlightShellState::new())
}

/// Shell metadata for one core `Highlight`, parallel to the engine's rule
/// list (same order, same length) — mirrors CriterionMeta.
struct HighlightMeta {
  mode: String,
  pattern: String,
  enabled: bool,
  override_color: Option<String>,
}

pub struct HighlightShellState {
  engine: HighlightEngine,
  meta: Vec<HighlightMeta>,
}

impl HighlightShellState {
  fn new() -> HighlightShellState {
    HighlightShellState { engine: HighlightEngine::new(), meta: Vec::new() }
  }
}

/// One §9 highlight rule of the snapshot: `id` = index (rule order) in the
/// highlights list of the LATEST snapshot.
#[derive(Debug, Clone, PartialEq, Serialize, specta::Type)]
pub struct HighlightDto {
  pub id: u32,
  pub mode: String,
  pub pattern: String,
  pub enabled: bool,
  pub color_index: u8,
  pub override_color: Option<String>,
}

/// One span of a RowDto (§9): a semi-transparent rectangle behind matched
/// text. SPEC NOTE: `start`/`len` are BYTE offsets inside the raw MESSAGE
/// text; the DTO deliberately keeps bytes raw — converting to JS string
/// indexes happens exactly once in ui/src/ipcClient.ts (single normalization
/// point). Overlapping rules are kept unmerged, in rule order, and a
/// disabled rule contributes nothing.
#[derive(Debug, Clone, PartialEq, Serialize, specta::Type)]
pub struct SpanDto {
  pub start: u32,
  pub len: u32,
  pub color_index: u8,
  pub override_color: Option<String>,
}

/// Mode tags of the contract — the same spellings the filters and search
/// use. For `lineno` the pattern is the LINE NUMBER of an `hn` rule, not a
/// matcher: a parseable number maps to the whole-line `Rule::LineNo`;
/// a non-number — the dsq.3 test precedent (`invalid_patterns_match_nothing`,
/// core `MatchMode::matcher`) — compiles to a never-matching pattern rule
/// that keeps its slot in the tab (like add_filter, it must not Err). An
/// unknown mode tag is refused (contract: mode is one of the four).
fn highlight_rule_from_parts(mode: &str, pattern: &str) -> Result<Rule, String> {
  match mode {
    "plain" => Ok(Rule::Pattern { matcher: Matcher::plain(pattern) }),
    "regex" => Ok(Rule::Pattern { matcher: Matcher::regex(pattern) }),
    "simple" => Ok(Rule::Pattern { matcher: Matcher::simple(pattern) }),
    "lineno" => Ok(pattern.trim().parse::<u32>().map_or_else(
      |_| Rule::Pattern { matcher: Matcher::never() },
      |n| Rule::LineNo { line_no: n },
    )),
    other => Err(format!("unknown mode {other:?}: expected plain|regex|simple|lineno")),
  }
}

/// Contract errors for the highlights list, in the dsq.3 style.
fn highlight_err(id: u32) -> String {
  format!("no such highlight {id}")
}

/// A user override color: CSS "#rrggbb" (seven chars, lowercase or
/// uppercase hex digits); anything else is bad input and is refused.
fn is_css_hex_color(s: &str) -> bool {
  s.len() == 7
    && s.starts_with('#')
    && s.as_bytes()[1..]
      .iter()
      .all(|&b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b) || (b'A'..=b'F').contains(&b))
}

pub(crate) fn add_highlight_inner(
  hl: &HighlightState,
  mode: &str,
  pattern: &str,
) -> Result<(), String> {
  let rule = highlight_rule_from_parts(mode, pattern)?;
  let mut guard = hl.lock().map_err(|_| lock_err())?;
  // The color rotation is the core engine's counter: the shell adds nothing
  // to it (continuity across removals is core behavior).
  guard.engine.add(rule);
  guard.meta.push(HighlightMeta {
    mode: mode.to_owned(),
    pattern: pattern.to_owned(),
    enabled: true,
    override_color: None,
  });
  Ok(())
}

pub(crate) fn remove_highlight_inner(hl: &HighlightState, id: u32) -> Result<(), String> {
  let id = id as usize;
  let mut guard = hl.lock().map_err(|_| lock_err())?;
  if id >= guard.meta.len() {
    return Err(highlight_err(id as u32));
  }
  guard.meta.remove(id);
  guard.engine.remove(id); // bounds-checked above, never panics
  Ok(())
}

pub(crate) fn set_highlight_enabled_inner(
  hl: &HighlightState,
  id: u32,
  on: bool,
) -> Result<(), String> {
  let id = id as usize;
  let mut guard = hl.lock().map_err(|_| lock_err())?;
  let meta = guard
    .meta
    .get_mut(id)
    .ok_or_else(|| highlight_err(id as u32))?;
  meta.enabled = on;
  guard.engine.set_enabled(id, on); // bounds-checked above, never panics
  Ok(())
}

pub(crate) fn set_highlight_color_inner(
  hl: &HighlightState,
  id: u32,
  hex: Option<String>,
) -> Result<(), String> {
  if let Some(hex) = &hex
    && !is_css_hex_color(hex)
  {
    return Err(format!(
      "bad highlight color {hex:?}: expected a CSS \"#rrggbb\" value"
    ));
  }
  let mut guard = hl.lock().map_err(|_| lock_err())?;
  let meta = guard
    .meta
    .get_mut(id as usize)
    .ok_or_else(|| highlight_err(id))?;
  meta.override_color = hex;
  Ok(())
}

pub(crate) fn clear_highlights_inner(hl: &HighlightState) -> Result<(), String> {
  let mut guard = hl.lock().map_err(|_| lock_err())?;
  guard.engine.clear();
  guard.meta.clear();
  Ok(())
}

/// Spans of one row over ACTIVE (enabled) rules only (§9: a semi-transparent
/// rectangle behind matched text, Message column only). This mirrors the
/// core `row_spans` rule by rule because it also needs the SHELL metadata
/// (the user override color) attached to the rule that produced each span,
/// which the core function does not return; the byte-range semantics are
/// the core's (`Matcher::spans`; LineNo colors the whole message). The two
/// lists inside `HighlightShellState` are parallel, so `idx` addresses both.
pub(crate) fn row_span_dtos(
  hl: &HighlightShellState,
  row: &logviewer_core::parser::Row,
) -> Vec<SpanDto> {
  let mut out = Vec::new();
  for (idx, h) in hl.engine.rules().iter().enumerate() {
    if !h.enabled {
      continue; // an off checkbox renders nothing (§9)
    }
    let ranges: Vec<(usize, usize)> = match &h.rule {
      Rule::Pattern { matcher } => matcher.spans(&row.message),
      // spec interpretation: an empty message is the zero-length `0..0`
      // (core doc comment); a zero-length span renders nothing.
      Rule::LineNo { line_no } => {
        if *line_no == row.line_no {
          vec![(0, row.message.len())]
        } else {
          Vec::new()
        }
      }
    };
    for (start, end) in ranges {
      out.push(SpanDto {
        start: start as u32,
        len: (end - start) as u32,
        color_index: h.color_index,
        override_color: hl.meta[idx].override_color.clone(),
      });
    }
  }
  out
}

/// The snapshot's highlight list: engine rule order, `id` = index.
fn highlight_dtos(hl: &HighlightShellState) -> Vec<HighlightDto> {
  hl
    .meta
    .iter()
    .enumerate()
    .map(|(id, m)| HighlightDto {
      id: id as u32,
      mode: m.mode.clone(),
      pattern: m.pattern.clone(),
      enabled: m.enabled,
      color_index: hl.engine.rules()[id].color_index,
      override_color: m.override_color.clone(),
    })
    .collect()
}

// ---------------------------------------------------------------- commands

/// Load a file in the background and make it the active model (§2).
/// Loading must not block the UI: this is an async command.
#[tauri::command]
#[specta::specta]
pub async fn load_file(
  path: String,
  state: tauri::State<'_, FileState>,
  vis: tauri::State<'_, VisState>,
) -> Result<LoadResult, String> {
  load_file_inner(std::path::Path::new(&path), &state, &vis)
}

/// Load implementation shared with the shell-crate tests (tauri::State cannot
/// be built outside an app).
pub(crate) fn load_file_inner(
  path: &std::path::Path,
  state: &FileState,
  vis: &VisState,
) -> Result<LoadResult, String> {
  let path = path.display().to_string();
  let (model, stats) = logviewer_core::workspace::FileModel::load_path(std::path::Path::new(&path))
    .map_err(|e| format!("cannot open {path}: {e}"))?;
  let result = to_load_result(&model, stats.elapsed.as_millis() as u32);
  // Lock order: file -> vis, exactly like every reader (get_rows / snapshot /
  // search take file first). Holding BOTH across the repopulate + swap keeps
  // a concurrent reader from building the visible cache against a mid-load
  // mixture of old model and new whitelist. The parse above runs before any
  // lock, so readers never wait on the file scan itself.
  let mut file = state.lock().map_err(|_| lock_err())?;
  let mut vis = vis.lock().map_err(|_| lock_err())?;
  // §12: a reload clears all pins entirely (filters, levels and disabled
  // categories persist; pins do not survive a reload).
  while !vis.pin_meta.is_empty() {
    vis.vis.remove_pin(0);
    vis.pin_meta.remove(0);
  }
  repopulate_categories(&mut vis, &model);
  *file = Some(model);
  vis.invalidate();
  Ok(result)
}

/// A window of the VISIBLE row sequence (§4, §7): `offset` indexes the rows
/// passing the combined §7 rule, not raw line numbers. The visible-line list
